# group interchangeable zeros and nines with symmetry by choosing named items sequence
# generic recursive most constrained cell; track placed items
def solve_tiling(drop_zero=None, allowrot=False, limit=100):
    active=[p for p in basepieces if p[0]!=drop_zero]
    op={}
    for name,h,w in active:
        op[name]=placements_for(h,w,allowrot)
    # index candidate placements by cells
    sol=[]; results=[]
    def rec(covered, unused, chosen):
        if len(results)>=limit:return
        if not unused:
            if covered==mask: results.append(chosen.copy())
            return
        # Must cover all covered target cells and area sums equal mask
        # choose first open cell, candidates among unused pieces covering it; also can detect area mismatch
        rem=mask-covered
        if sum(next(x[1]*x[2] for x in active if x[0]==nm) for nm in unused)!=len(rem): return
        best=[]; cellbest=None
        for cell in rem:
            cand=[]
            for nm in unused:
                for pl in op[nm]:
                    if cell in pl[4] and pl[4] <= rem:
                        cand.append((nm,pl))
            if not cand: return
            if cellbest is None or len(cand)<len(best):best=cand;cellbest=cell
            if len(best)==1:break
        # Avoid sym duplicate identical pieces by ordering chosen positions for same shape names
        for nm,pl in best:
            name,h,w=next(p for p in active if p[0]==nm)
            # apply duplicate canonical ordering across same dims, but piece names could different colors e.g fourA,B/patA,B shouldn't canonical same since colors differ although dimensions same
            newunused=unused-{nm}
            rec(covered|pl[4],newunused,chosen+[(nm,pl)])
    rec(set(),{p[0] for p in active},[])
    return results
